using System;using System.IO;using System.Diagnostics;using System.Reflection;using System.Linq;
class BootstrapTests {
 static int Main(string[] a){if(a.Length>0&&a[0]=="--echo"){File.WriteAllLines(a[1],a.Skip(2));return 0;}int failed=0;Action<string,Action> test=(n,f)=>{try{f();Console.WriteLine("PASS "+n);}catch(Exception e){failed++;Console.WriteLine("FAIL "+n+" "+e.Message);}};
 test("Windows installer arguments round trip",()=>{string root=Path.Combine(Path.GetTempPath(),"asterhub-args-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string output=Path.Combine(root,"result.txt");string[] expected={"/DIR=C:\\Program Files\\测试 AsterHub\\","/AQPID=12","/LOG=C:\\a b\\log.txt","quote\"inside","","two\\\\\"quotes"};var values=new[]{"--echo",output}.Concat(expected).ToArray();var child=Process.Start(new ProcessStartInfo(Assembly.GetExecutingAssembly().Location,BootstrapCore.JoinArguments(values)){UseShellExecute=false,CreateNoWindow=true});if(!child.WaitForExit(10000)||child.ExitCode!=0||!File.ReadAllLines(output).SequenceEqual(expected))throw new Exception("Argument round trip failed");File.Delete(output);Directory.Delete(root);});
 test("Embedded full installer signature and exact payload",()=>{var r=BootstrapCore.ReadRelease();if(r.version!="0.3.0-preview.22"||r.installerBytes!=26019811||r.installerSha256!="332a375d3caa72463dbaa24498c1993d5761f14c5991afb6297c24c6c27a96d0")throw new Exception("Incorrect payload");});
 test("Wrong version and recursive target rejected",()=>{foreach(var r in new[]{new ReleaseInfo{version="0.3.0-preview.21",installerUrl="https://example.com/setup.exe"},new ReleaseInfo{version="0.3.0-preview.22",installerUrl="https://example.com/AsterHub-Update-0.3.0-preview.22.exe"}}){bool denied=false;try{BootstrapCore.Validate(r);}catch(InvalidDataException){denied=true;}if(!denied)throw new Exception("Unsafe target accepted");}});
 return failed==0?0:1;}
}
